/**
 * Visual builder model (PLAN.md §5 "Visueller Builder"). The builder produces nothing but template HTML and CSS in the
 * normal template language; the model travels inside the generated HTML (attribute data-swp-builder), so code that
 * was generated by the builder can be opened in the builder again, and code that was edited by hand is recognised
 * as such (isGeneratedFrom) instead of being silently overwritten.
 *
 * @since 0.1.0
 */

export const BUILDER_VERSION = 1;
export const MAX_DEPTH = 5;
export const MAX_NODES = 60;

export type Direction = 'column' | 'row';

export type BuilderNode =
  | { type: 'image'; size: string; link: boolean }
  | { type: 'title'; tag: 'h2' | 'h3' | 'h4'; link: boolean }
  | { type: 'excerpt'; words: number }
  | { type: 'date'; format: string; relative: boolean }
  | { type: 'author'; link: boolean }
  | { type: 'taxonomy'; taxonomy: string; links: boolean; separator: string }
  | { type: 'meta'; key: string; label: string; fallback: string }
  | { type: 'readmore'; label: string }
  | { type: 'text'; text: string }
  | { type: 'spacer'; height: number }
  | {
      type: 'container';
      direction: Direction;
      gap: number;
      padding: number;
      background: string;
      children: BuilderNode[];
    };

export type ContainerNode = Extract<BuilderNode, { type: 'container' }>;

export interface BuilderModel {
  version: typeof BUILDER_VERSION;
  root: ContainerNode;
}

export const NODE_TYPES = [
  'image',
  'title',
  'excerpt',
  'date',
  'author',
  'taxonomy',
  'meta',
  'readmore',
  'text',
  'container',
  'spacer',
] as const;
export type NodeType = (typeof NODE_TYPES)[number];

export const IMAGE_SIZES = ['thumbnail', 'medium', 'medium_large', 'large', 'full'];
const FORMAT_PATTERN = /^[A-Za-z0-9 .,:/-]{1,30}$/;
const SEPARATOR_PATTERN = /^[^"\\{}<>]{0,20}$/;
const KEY_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const TAXONOMY_PATTERN = /^[a-z0-9_-]{1,32}$/;
const COLOR_PATTERN = /^(#[0-9a-fA-F]{6})?$/;

/** A new node of a type with usable defaults. */
export function createNode(type: NodeType): BuilderNode {
  switch (type) {
    case 'image':
      return { type, size: 'medium_large', link: true };
    case 'title':
      return { type, tag: 'h3', link: true };
    case 'excerpt':
      return { type, words: 30 };
    case 'date':
      return { type, format: 'd.m.Y', relative: false };
    case 'author':
      return { type, link: false };
    case 'taxonomy':
      return { type, taxonomy: 'category', links: true, separator: ', ' };
    case 'meta':
      return { type, key: 'subtitle', label: '', fallback: '' };
    case 'readmore':
      return { type, label: 'Read more' };
    case 'text':
      return { type, text: 'Text' };
    case 'spacer':
      return { type, height: 16 };
    case 'container':
      return { type, direction: 'column', gap: 8, padding: 0, background: '', children: [] };
  }
}

export function emptyModel(): BuilderModel {
  return {
    version: BUILDER_VERSION,
    root: {
      type: 'container',
      direction: 'column',
      gap: 8,
      padding: 0,
      background: '',
      children: [],
    },
  };
}

/** The classic card: image, then a column with title, date and excerpt. */
export function defaultModel(): BuilderModel {
  const model = emptyModel();
  model.root.children = [
    createNode('image'),
    {
      type: 'container',
      direction: 'column',
      gap: 6,
      padding: 12,
      background: '',
      children: [
        createNode('title'),
        createNode('date'),
        createNode('excerpt'),
        createNode('readmore'),
      ],
    },
  ];
  return model;
}

const escapeText = (text: string): string =>
  text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/\{/g, '&#123;')
    .replace(/\}/g, '&#125;');

const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, Math.round(value)));

interface Output {
  html: string;
  css: string[];
  counter: number;
}

function node(item: BuilderNode, out: Output): string {
  switch (item.type) {
    case 'image': {
      const image = `{{entry.image|image:"${item.size}"}}`;
      const inner = item.link
        ? `<a class="swp-b-image" href="{{entry.url}}">${image}</a>`
        : `<div class="swp-b-image">${image}</div>`;
      return `{{#entry.image}}${inner}{{/entry.image}}`;
    }
    case 'title': {
      const text = item.link ? '<a href="{{entry.url}}">{{entry.title}}</a>' : '{{entry.title}}';
      return `<${item.tag} class="swp-b-title">${text}</${item.tag}>`;
    }
    case 'excerpt':
      return `{{#entry.excerpt}}<p class="swp-b-excerpt">{{entry.excerpt|words:${clamp(item.words, 1, 200)}}}</p>{{/entry.excerpt}}`;
    case 'date': {
      const text = item.relative
        ? '{{entry.date|relative_date}}'
        : `{{entry.date|date:"${item.format}"}}`;
      return `<time class="swp-b-date" datetime='{{entry.date|date:"c"}}'>${text}</time>`;
    }
    case 'author': {
      const text = item.link
        ? '<a href="{{entry.author.url}}">{{entry.author.name}}</a>'
        : '{{entry.author.name}}';
      return `<span class="swp-b-author">${text}</span>`;
    }
    case 'taxonomy': {
      const name = `entry.terms.${item.taxonomy}`;
      const formatter = item.links ? 'link' : 'join';
      return `{{#${name}}}<p class="swp-b-terms">{{${name}|${formatter}:"${item.separator}"}}</p>{{/${name}}}`;
    }
    case 'meta': {
      const name = `entry.meta.${item.key}`;
      const label = item.label === '' ? '' : `<strong>${escapeText(item.label)}</strong> `;
      if (item.fallback !== '') {
        return `<p class="swp-b-meta">${label}{{${name}|default:"${item.fallback.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"}}</p>`;
      }
      return `{{#${name}}}<p class="swp-b-meta">${label}{{${name}}}</p>{{/${name}}}`;
    }
    case 'readmore':
      return `<a class="swp-b-more" href="{{entry.url}}">${escapeText(item.label)}</a>`;
    case 'text':
      return `<p class="swp-b-text">${escapeText(item.text)}</p>`;
    case 'spacer': {
      out.counter += 1;
      const cls = `swp-b-n${out.counter}`;
      out.css.push(`.${cls}{height:${clamp(item.height, 0, 200)}px}`);
      return `<div class="swp-b-spacer ${cls}" aria-hidden="true"></div>`;
    }
    case 'container':
      return container(item, out, 'div');
  }
}

function container(
  item: ContainerNode,
  out: Output,
  tag: 'div' | 'article',
  attributes = '',
): string {
  out.counter += 1;
  const cls = `swp-b-n${out.counter}`;
  const background = item.background === '' ? '' : `background:${item.background.toLowerCase()};`;
  out.css.push(
    `.${cls}{display:flex;flex-direction:${item.direction};gap:${clamp(item.gap, 0, 64)}px;padding:${clamp(item.padding, 0, 64)}px;${background}}`,
  );
  const children = item.children.map((child) => node(child, out)).join('');
  return `<${tag} class="${tag === 'article' ? 'swp-b ' : 'swp-b-box '}${cls}"${attributes}>${children}</${tag}>`;
}

function encodeModel(model: BuilderModel): string {
  const bytes = new TextEncoder().encode(JSON.stringify(model));
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function decodeModel(encoded: string): unknown {
  const padded =
    encoded.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (encoded.length % 4)) % 4);
  const binary = atob(padded);
  return JSON.parse(
    new TextDecoder().decode(Uint8Array.from(binary, (char) => char.charCodeAt(0))),
  ) as unknown;
}

/** Template HTML and CSS for a model. The model is embedded so the builder can read it back. */
export function generate(model: BuilderModel): { html: string; css: string } {
  const out: Output = {
    html: '',
    css: [
      '.swp-b img{display:block;max-width:100%;height:auto}',
      '.swp-b-title{margin:0}',
      '.swp-b p{margin:0}',
    ],
    counter: 0,
  };
  const html = container(model.root, out, 'article', ` data-swp-builder="${encodeModel(model)}"`);
  return { html, css: out.css.join('\n') };
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const num = (value: unknown, min: number, max: number): boolean =>
  typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;

function validNode(value: unknown, depth: number, state: { count: number }): value is BuilderNode {
  state.count += 1;
  if (!isObject(value) || state.count > MAX_NODES || typeof value.type !== 'string') return false;
  switch (value.type) {
    case 'image':
      return (
        typeof value.size === 'string' &&
        IMAGE_SIZES.includes(value.size) &&
        typeof value.link === 'boolean'
      );
    case 'title':
      return ['h2', 'h3', 'h4'].includes(String(value.tag)) && typeof value.link === 'boolean';
    case 'excerpt':
      return num(value.words, 1, 200);
    case 'date':
      return (
        typeof value.format === 'string' &&
        FORMAT_PATTERN.test(value.format) &&
        typeof value.relative === 'boolean'
      );
    case 'author':
      return typeof value.link === 'boolean';
    case 'taxonomy':
      return (
        typeof value.taxonomy === 'string' &&
        TAXONOMY_PATTERN.test(value.taxonomy) &&
        typeof value.links === 'boolean' &&
        typeof value.separator === 'string' &&
        SEPARATOR_PATTERN.test(value.separator)
      );
    case 'meta':
      return (
        typeof value.key === 'string' &&
        KEY_PATTERN.test(value.key) &&
        typeof value.label === 'string' &&
        value.label.length <= 60 &&
        typeof value.fallback === 'string' &&
        value.fallback.length <= 60
      );
    case 'readmore':
      return typeof value.label === 'string' && value.label.length > 0 && value.label.length <= 60;
    case 'text':
      return typeof value.text === 'string' && value.text.length <= 1000;
    case 'spacer':
      return num(value.height, 0, 200);
    case 'container':
      return (
        depth < MAX_DEPTH &&
        (value.direction === 'column' || value.direction === 'row') &&
        num(value.gap, 0, 64) &&
        num(value.padding, 0, 64) &&
        typeof value.background === 'string' &&
        COLOR_PATTERN.test(value.background) &&
        Array.isArray(value.children) &&
        value.children.every((child) => validNode(child, depth + 1, state))
      );
    default:
      return false;
  }
}

/** Whether a decoded value is a well-formed model (bounded depth and size, validated options). */
export function isValidModel(value: unknown): value is BuilderModel {
  return (
    isObject(value) &&
    value.version === BUILDER_VERSION &&
    isObject(value.root) &&
    value.root.type === 'container' &&
    validNode(value.root, 0, { count: 0 })
  );
}

/** The model embedded in builder generated HTML, or null for hand written (or damaged) code. */
export function parseModel(html: string): BuilderModel | null {
  const match = /data-swp-builder="([A-Za-z0-9_-]+)"/.exec(html);
  if (match === null) return null;
  try {
    const decoded = decodeModel(match[1] as string);
    return isValidModel(decoded) ? decoded : null;
  } catch {
    return null;
  }
}

/** True when the code is exactly what the builder generates for the model, so builder edits lose nothing. */
export function isGeneratedFrom(html: string, css: string, model: BuilderModel): boolean {
  const generated = generate(model);
  return html === generated.html && css === generated.css;
}
